# rrvgo: reduce redundant GO BP terms from Zeisel 2015 astrocyte markers (treemap, scatter, wordcloud-style heatmap)
suppressPackageStartupMessages({library(rrvgo); library(clusterProfiler); library(org.Mm.eg.db); library(dplyr); library(ggplot2)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE)))); if (!file.exists("../_data/zeisel_markers.csv")) system("Rscript ../_data/zeisel_de.R")
m <- read.csv("../_data/zeisel_markers.csv") %>% filter(cluster == "astrocytes_ependymal", p_val_adj < .01) %>% slice_max(avg_log2FC, n = 300)
ego <- as.data.frame(enrichGO(m$gene, OrgDb = org.Mm.eg.db, keyType = "SYMBOL", ont = "BP", pvalueCutoff = .01))
sim <- calculateSimMatrix(ego$ID, orgdb = "org.Mm.eg.db", ont = "BP", method = "Rel")
sc <- setNames(-log10(ego$p.adjust), ego$ID); red <- reduceSimMatrix(sim, sc, threshold = .7, orgdb = "org.Mm.eg.db")
png("v1_treemap.png", 1600, 1100, res = 150); treemapPlot(red, title = "rrvgo treemap: astrocyte marker GO BP (parents)"); dev.off()
ggsave("v2_scatter.png", scatterPlot(sim, red, labelSize = 3) + ggtitle("rrvgo semantic-similarity scatter"), width = 9, height = 7, dpi = 130, bg = "white")
png("v3_heatmap.png", 1500, 1300, res = 140); heatmapPlot(sim, red, annotateParent = TRUE, annotationLabel = "parentTerm", fontsize = 5); dev.off()
